	// Module 10 redesign — renders any agent-applied JSON-LD blocks (CollectionPage,
	// etc.) from PageSchema/Mongo, alongside the hardcoded blocks above.
	addDynamicSchema() {
		this.pageSchemaService.getPageSchema('projects').subscribe((blocks) => {
			for (const block of blocks) {
				const existing = this.document.getElementById(`schema-agent-${block.schemaType}`);
				if (existing) existing.remove();
				const script = this.document.createElement('script');
				script.type = 'application/ld+json';
				script.id = `schema-agent-${block.schemaType}`;
				script.textContent = block.jsonLd;
				this.document.head.appendChild(script);
			}
		});
	}

