	// Fetch all projects with pagination
	get_AllProjects1(): void {
		const obj = { limit: this.currentLimit, page: this.currentPage };
		this.projectservice.getAllProjects(obj).subscribe(
			(response: any) => {
				const result = response?.result ?? response?.data ?? [];
				const total = response?.count ?? response?.total ?? result.length;

				if (response?.code === 200 && Array.isArray(result)) {
					// Add unique projects to avoid duplicates
					const newProjects = result.filter(
						(project: any) => project.status && !this.allprojects1.some((p) => p._id === project._id)
					);
					this.allprojects1 = [...this.allprojects1, ...newProjects]; // Append new projects
					this.totalProjects = total; // Update total project count
					if (this.totalProjects < this.currentLimit) {
						this.isMorePrasent = false;
					}
					this.applyFilter(); // Filter and display projects
					this.cdr.detectChanges();
				}
			},
			(error) => {
				console.error('Failed to fetch projects:', error);
			}
		);
	}

	// Filter projects based on selected category and update displayed projects
	applyFilter(): void {
		this.filteredProjects =
			this.selectedCategory === 'all'
				? [...this.allprojects1]
				: this.allprojects1.filter((project) => this.projectMatchesCategory(project, this.selectedCategory));

		const projectsToShow = this.filteredProjects.slice(0, this.currentPage * this.currentLimit);
		this.displayedProjects = projectsToShow;
		this.isMorePrasent = this.selectedCategory === 'all' && this.displayedProjects.length < this.totalProjects;
		this.cdr.detectChanges();
	}

